        let given = |t: &Ticket| {
            let plans: Vec<PathBuf> = lane_plans(t, &p, None)
                .into_iter()
                .map(|(_, plan)| plan.clone())
                .collect();
            (
                lane_plan(t, &p, Some("A")).cloned(),
                plans,
                field(&vars_for(t, &p, Some("A")), "inputs.plan"),
                plan_clause(t, &p, None),
